//! CRC16-CCITT and CRC32 checksum algorithms and frame verification for DJI `.DAT` files.
//!
//! DJI `.DAT` on-board blackbox streams use:
//! - CRC16-CCITT (polynomial `0x1021`, initial value `0x3692` with fallback `0xFFFF`) for
//!   standard sensor telemetry frames (IMU, GPS, Battery, etc.).
//! - IEEE 802.3 CRC32 (polynomial `0xEDB88320`, initial value `0xFFFFFFFF`) for
//!   extended multi-sector frames.

use crate::error::{FlightReaderError, Result};

/// CRC16-CCITT generator polynomial ($x^{16} + x^{12} + x^5 + 1$).
pub const CRC16_POLYNOMIAL: u16 = 0x1021;

/// Primary initial seed used by DJI flight controllers for `.DAT` CRC16 checksums.
pub const CRC16_INIT_PRIMARY: u16 = 0x3692;

/// Secondary fallback initial seed used by certain legacy or alternate DJI firmware.
pub const CRC16_INIT_FALLBACK: u16 = 0xFFFF;

/// IEEE 802.3 32-bit generator polynomial (reversed / LSB-first).
pub const CRC32_POLYNOMIAL: u32 = 0xEDB8_8320;

/// Compile-time precomputed lookup table for CRC16-CCITT (polynomial `0x1021`).
const CRC16_TABLE: [u16; 256] = {
    let mut table = [0u16; 256];
    let mut i = 0;
    while i < 256 {
        let mut crc = (i as u16) << 8;
        let mut j = 0;
        while j < 8 {
            if (crc & 0x8000) != 0 {
                crc = ((crc << 1) ^ CRC16_POLYNOMIAL) & 0xFFFF;
            } else {
                crc = (crc << 1) & 0xFFFF;
            }
            j += 1;
        }
        table[i] = crc;
        i += 1;
    }
    table
};

/// Compile-time precomputed lookup table for IEEE 802.3 CRC32 (polynomial `0xEDB88320`).
const CRC32_TABLE: [u32; 256] = {
    let mut table = [0u32; 256];
    let mut i = 0;
    while i < 256 {
        let mut crc = i as u32;
        let mut j = 0;
        while j < 8 {
            if (crc & 1) != 0 {
                crc = (crc >> 1) ^ CRC32_POLYNOMIAL;
            } else {
                crc >>= 1;
            }
            j += 1;
        }
        table[i] = crc;
        i += 1;
    }
    table
};

/// Computes the 16-bit CRC16-CCITT checksum over `data` with the given initial value.
///
/// # Arguments
/// * `data` - Byte slice over which to compute the checksum.
/// * `init_val` - Initial CRC register value (`0x3692` for DJI primary, `0xFFFF` for fallback).
///
/// # Examples
/// ```
/// use flightreader_core::dat::checksum::{calc_crc16_ccitt, CRC16_INIT_PRIMARY};
///
/// let header_and_payload = [0x55, 0x0B, 0x00, 0x01, 0x00, 0xE8, 0x03, 0x00, 0x00];
/// let crc = calc_crc16_ccitt(&header_and_payload, CRC16_INIT_PRIMARY);
/// assert_eq!(crc, 0x5184);
/// ```
#[inline]
pub fn calc_crc16_ccitt(data: &[u8], init_val: u16) -> u16 {
    let mut crc = init_val;
    for &b in data {
        let idx = (((crc >> 8) ^ (b as u16)) & 0xFF) as usize;
        crc = (crc << 8) ^ CRC16_TABLE[idx];
    }
    crc
}

/// Verifies the 16-bit CRC16-CCITT checksum at the end of a `.DAT` frame slice.
///
/// The checksum is verified by calculating the CRC16 over `&frame_bytes[0 .. frame_bytes.len() - 2]`
/// with the primary initial value `0x3692` (and optional fallback `0xFFFF`), then comparing
/// against the Little-Endian `u16` stored in the final 2 bytes.
///
/// # Errors
/// * Returns `FlightReaderError::InvalidFrameLength` if `frame_bytes.len() < 11`.
/// * Returns `FlightReaderError::ChecksumMismatch` if neither the primary nor fallback CRC matches.
pub fn verify_crc16(frame_bytes: &[u8]) -> Result<()> {
    if frame_bytes.len() < 11 {
        return Err(FlightReaderError::InvalidFrameLength {
            length: frame_bytes.len() as u8,
            minimum: 11,
        });
    }

    let len = frame_bytes.len();
    let expected = u16::from_le_bytes([frame_bytes[len - 2], frame_bytes[len - 1]]);
    let data = &frame_bytes[..len - 2];

    let calc_primary = calc_crc16_ccitt(data, CRC16_INIT_PRIMARY);
    if calc_primary == expected {
        return Ok(());
    }

    let calc_fallback = calc_crc16_ccitt(data, CRC16_INIT_FALLBACK);
    if calc_fallback == expected {
        return Ok(());
    }

    Err(FlightReaderError::ChecksumMismatch {
        expected: expected as u32,
        calculated: calc_primary as u32,
    })
}

/// Verifies the 16-bit CRC16-CCITT checksum of a frame using a specific initial seed.
///
/// # Errors
/// * Returns `FlightReaderError::InvalidFrameLength` if `frame_bytes.len() < 11`.
/// * Returns `FlightReaderError::ChecksumMismatch` if the calculated checksum differs from expected.
pub fn verify_crc16_with_seed(frame_bytes: &[u8], seed: u16) -> Result<()> {
    if frame_bytes.len() < 11 {
        return Err(FlightReaderError::InvalidFrameLength {
            length: frame_bytes.len() as u8,
            minimum: 11,
        });
    }

    let len = frame_bytes.len();
    let expected = u16::from_le_bytes([frame_bytes[len - 2], frame_bytes[len - 1]]);
    let data = &frame_bytes[..len - 2];
    let calculated = calc_crc16_ccitt(data, seed);

    if calculated == expected {
        Ok(())
    } else {
        Err(FlightReaderError::ChecksumMismatch {
            expected: expected as u32,
            calculated: calculated as u32,
        })
    }
}

/// Computes the standard IEEE 802.3 32-bit CRC (Ethernet / zlib) over `data`.
///
/// Uses generator polynomial `0xEDB88320` with initial value `0xFFFFFFFF` and final XOR `0xFFFFFFFF`.
///
/// # Examples
/// ```
/// use flightreader_core::dat::checksum::calc_crc32;
///
/// let data = b"123456789";
/// assert_eq!(calc_crc32(data), 0xCBF4_3926);
/// ```
#[inline]
pub fn calc_crc32(data: &[u8]) -> u32 {
    let mut crc = 0xFFFF_FFFFu32;
    for &b in data {
        let idx = ((crc ^ (b as u32)) & 0xFF) as usize;
        crc = (crc >> 8) ^ CRC32_TABLE[idx];
    }
    crc ^ 0xFFFF_FFFF
}

/// Verifies the 32-bit IEEE 802.3 CRC32 checksum at the end of a `.DAT` frame slice.
///
/// The checksum is verified by calculating the CRC32 over `&frame_bytes[0 .. frame_bytes.len() - 4]`,
/// then comparing against the Little-Endian `u32` stored in the final 4 bytes.
///
/// # Errors
/// * Returns `FlightReaderError::InvalidFrameLength` if `frame_bytes.len() < 13`.
/// * Returns `FlightReaderError::ChecksumMismatch` if the calculated checksum differs from expected.
pub fn verify_crc32(frame_bytes: &[u8]) -> Result<()> {
    if frame_bytes.len() < 13 {
        return Err(FlightReaderError::InvalidFrameLength {
            length: frame_bytes.len() as u8,
            minimum: 13,
        });
    }

    let len = frame_bytes.len();
    let expected = u32::from_le_bytes([
        frame_bytes[len - 4],
        frame_bytes[len - 3],
        frame_bytes[len - 2],
        frame_bytes[len - 1],
    ]);
    let data = &frame_bytes[..len - 4];
    let calculated = calc_crc32(data);

    if calculated == expected {
        Ok(())
    } else {
        Err(FlightReaderError::ChecksumMismatch {
            expected,
            calculated,
        })
    }
}

