//! DJI `.DAT` blackbox binary frame parsing and stream iterator.
//!
//! Provides zero-allocation parsing of `.DAT` binary telemetry frames,
//! payload extraction, and a resilient synchronization iterator for scanning
//! corrupted or noisy raw streams.

use crate::dat::checksum;
use crate::error::{FlightReaderError, Result};

/// Synchronization magic byte for all DJI `.DAT` blackbox frames (`0x55` / `85` decimal).
pub const DAT_MAGIC: u8 = 0x55;

/// Length of the fixed frame header in bytes (Magic, Length, Sequence, PayloadID, Timestamp).
pub const HEADER_LEN: usize = 9;

/// The checksum verification algorithm utilized by a `.DAT` telemetry frame.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum DatChecksumType {
    /// 16-bit CCITT checksum (2 bytes). Used by standard sensor frames (IMU, GPS, Battery).
    Crc16,
    /// 32-bit IEEE 802.3 checksum (4 bytes). Used by extended multi-sector frames.
    Crc32,
}

impl DatChecksumType {
    /// Returns the length of the checksum field in bytes (2 for CRC16, 4 for CRC32).
    #[inline]
    pub const fn checksum_len(&self) -> usize {
        match self {
            DatChecksumType::Crc16 => 2,
            DatChecksumType::Crc32 => 4,
        }
    }

    /// Returns the minimum physical frame length in bytes for this checksum type
    /// (9-byte header + checksum length).
    #[inline]
    pub const fn min_frame_len(&self) -> usize {
        HEADER_LEN + self.checksum_len()
    }
}

/// A zero-allocation borrowed view of a parsed DJI `.DAT` blackbox telemetry frame.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DatFrame<'a> {
    /// Synchronization magic byte (must be `0x55`).
    pub magic: u8,
    /// Total frame length in bytes including header, payload, and checksum.
    pub length: u8,
    /// Frame sequence counter or sub-header flag.
    pub sequence: u8,
    /// Telemetry sensor payload type identifier.
    pub payload_id: u16,
    /// Microsecond clock counter ticks since flight controller boot.
    pub timestamp_ticks: u32,
    /// Borrowed slice containing the raw telemetry payload bytes.
    pub payload: &'a [u8],
    /// Checksum algorithm validated for this frame.
    pub checksum_type: DatChecksumType,
}

impl<'a> DatFrame<'a> {
    /// Parses a single `.DAT` frame from a borrowed byte slice with zero allocations.
    ///
    /// Validates the `0x55` magic byte, checks the minimum frame length, verifies
    /// the frame checksum (attempting CRC16 first with primary `0x3692` and fallback `0xFFFF`,
    /// then CRC32 if length $\ge 13$), and extracts the raw payload slice.
    ///
    /// # Errors
    /// * Returns `FlightReaderError::UnexpectedEof` if `frame_bytes` is empty.
    /// * Returns `FlightReaderError::SyncNotFound` if `frame_bytes[0] != 0x55`.
    /// * Returns `FlightReaderError::InvalidFrameLength` if declared length $< 11$.
    /// * Returns `FlightReaderError::TruncatedRecord` if `frame_bytes.len() < length`.
    /// * Returns `FlightReaderError::ChecksumMismatch` if checksum verification fails.
    pub fn parse(frame_bytes: &'a [u8]) -> Result<DatFrame<'a>> {
        if frame_bytes.is_empty() {
            return Err(FlightReaderError::UnexpectedEof);
        }

        if frame_bytes[0] != DAT_MAGIC {
            return Err(FlightReaderError::SyncNotFound);
        }

        if frame_bytes.len() < 2 {
            return Err(FlightReaderError::UnexpectedEof);
        }

        let length = frame_bytes[1];
        if (length as usize) < 11 {
            return Err(FlightReaderError::InvalidFrameLength {
                length,
                minimum: 11,
            });
        }

        if frame_bytes.len() < length as usize {
            return Err(FlightReaderError::TruncatedRecord {
                expected: length as usize,
                available: frame_bytes.len(),
            });
        }

        let frame_slice = &frame_bytes[..length as usize];

        // Determine checksum type and verify
        let (checksum_type, checksum_len) = match checksum::verify_crc16(frame_slice) {
            Ok(()) => (DatChecksumType::Crc16, 2),
            Err(crc16_err) => {
                if (length as usize) >= 13 {
                    match checksum::verify_crc32(frame_slice) {
                        Ok(()) => (DatChecksumType::Crc32, 4),
                        Err(_) => return Err(crc16_err),
                    }
                } else {
                    return Err(crc16_err);
                }
            }
        };

        let sequence = frame_slice[2];
        let payload_id = u16::from_le_bytes([frame_slice[3], frame_slice[4]]);
        let timestamp_ticks = u32::from_le_bytes([
            frame_slice[5],
            frame_slice[6],
            frame_slice[7],
            frame_slice[8],
        ]);
        let payload = &frame_slice[HEADER_LEN..length as usize - checksum_len];

        Ok(DatFrame {
            magic: DAT_MAGIC,
            length,
            sequence,
            payload_id,
            timestamp_ticks,
            payload,
            checksum_type,
        })
    }

    /// Parses a single `.DAT` frame with an explicitly specified checksum type.
    ///
    /// # Errors
    /// * Returns `FlightReaderError::InvalidFrameLength` if length is smaller than the checksum's minimum.
    /// * Returns `FlightReaderError::ChecksumMismatch` if the specified checksum does not match.
    pub fn parse_with_checksum(
        frame_bytes: &'a [u8],
        checksum_type: DatChecksumType,
    ) -> Result<DatFrame<'a>> {
        if frame_bytes.is_empty() {
            return Err(FlightReaderError::UnexpectedEof);
        }

        if frame_bytes[0] != DAT_MAGIC {
            return Err(FlightReaderError::SyncNotFound);
        }

        if frame_bytes.len() < 2 {
            return Err(FlightReaderError::UnexpectedEof);
        }

        let length = frame_bytes[1];
        let min_len = checksum_type.min_frame_len();
        if (length as usize) < min_len {
            return Err(FlightReaderError::InvalidFrameLength {
                length,
                minimum: min_len,
            });
        }

        if frame_bytes.len() < length as usize {
            return Err(FlightReaderError::TruncatedRecord {
                expected: length as usize,
                available: frame_bytes.len(),
            });
        }

        let frame_slice = &frame_bytes[..length as usize];

        match checksum_type {
            DatChecksumType::Crc16 => checksum::verify_crc16(frame_slice)?,
            DatChecksumType::Crc32 => checksum::verify_crc32(frame_slice)?,
        }

        let sequence = frame_slice[2];
        let payload_id = u16::from_le_bytes([frame_slice[3], frame_slice[4]]);
        let timestamp_ticks = u32::from_le_bytes([
            frame_slice[5],
            frame_slice[6],
            frame_slice[7],
            frame_slice[8],
        ]);
        let payload = &frame_slice[HEADER_LEN..length as usize - checksum_type.checksum_len()];

        Ok(DatFrame {
            magic: DAT_MAGIC,
            length,
            sequence,
            payload_id,
            timestamp_ticks,
            payload,
            checksum_type,
        })
    }
}

/// An iterator that scans and extracts valid `.DAT` telemetry frames from a byte stream.
///
/// Handles noisy streams, embedded corruptions, and invalid candidate headers by
/// advancing byte-by-byte until a verifiable frame is located, then advancing by `frame.length`.
#[derive(Debug, Clone)]
pub struct DatFrameIterator<'a> {
    buffer: &'a [u8],
    cursor: usize,
}

impl<'a> DatFrameIterator<'a> {
    /// Creates a new `DatFrameIterator` over the given byte buffer.
    pub fn new(buffer: &'a [u8]) -> Self {
        Self { buffer, cursor: 0 }
    }

    /// Returns the current read cursor position within the buffer.
    pub fn cursor(&self) -> usize {
        self.cursor
    }

    /// Returns the remaining unconsumed slice of the buffer.
    pub fn remaining(&self) -> &'a [u8] {
        if self.cursor >= self.buffer.len() {
            &[]
        } else {
            &self.buffer[self.cursor..]
        }
    }
}

impl<'a> Iterator for DatFrameIterator<'a> {
    type Item = Result<DatFrame<'a>>;

    fn next(&mut self) -> Option<Self::Item> {
        while self.cursor < self.buffer.len() {
            // Find next occurrence of 0x55 magic byte
            let rel_sync = match self.buffer[self.cursor..].iter().position(|&b| b == DAT_MAGIC) {
                Some(pos) => pos,
                None => {
                    self.cursor = self.buffer.len();
                    return None;
                }
            };

            let sync_pos = self.cursor + rel_sync;
            self.cursor = sync_pos;

            // Must have at least 2 bytes (magic + length) to evaluate candidate
            if self.cursor + 1 >= self.buffer.len() {
                self.cursor = self.buffer.len();
                return None;
            }

            let cand_len = self.buffer[self.cursor + 1] as usize;

            // Minimum allowable frame length for any checksum type is 11 bytes
            if cand_len < 11 {
                self.cursor += 1;
                continue;
            }

            // Check if full candidate frame is available in the buffer
            if self.cursor + cand_len > self.buffer.len() {
                self.cursor += 1;
                continue;
            }

            let cand_slice = &self.buffer[self.cursor..self.cursor + cand_len];

            match DatFrame::parse(cand_slice) {
                Ok(frame) => {
                    self.cursor += cand_len;
                    return Some(Ok(frame));
                }
                Err(_) => {
                    // Checksum or format verification failed, advance 1 byte to seek next sync
                    self.cursor += 1;
                    continue;
                }
            }
        }

        None
    }
}

